-- V1__create_tables.sql
CREATE TABLE accounts (
    id          VARCHAR(20) PRIMARY KEY,
    holder_name VARCHAR(100) NOT NULL
);
CREATE TABLE transactions (
    txn_id     VARCHAR(24) PRIMARY KEY,
    account_id VARCHAR(20),          -- nullable to demonstrate outer joins
    amount     DECIMAL(15,2) NOT NULL
);
CREATE TABLE offers (code VARCHAR(10) PRIMARY KEY, name VARCHAR(40) NOT NULL);
CREATE TABLE employees (
    emp_id     INT PRIMARY KEY,
    name       VARCHAR(60) NOT NULL,
    manager_id INT                    -- points at another employees.emp_id
);

