```sql
-- INNER: only accounts WITH transactions.
SELECT a.id, t.txn_id FROM accounts a JOIN transactions t ON t.account_id = a.id;

-- LEFT: ALL accounts; dormant ones show NULL txn.
SELECT a.id, t.txn_id FROM accounts a LEFT JOIN transactions t ON t.account_id = a.id;

-- LEFT anti-join: accounts that NEVER transacted.
SELECT a.id FROM accounts a LEFT JOIN transactions t ON t.account_id = a.id WHERE t.txn_id IS NULL;

-- FULL: everything from both sides (incl. the account_id=NULL txn and dormant account).
SELECT a.id, t.txn_id FROM accounts a FULL OUTER JOIN transactions t ON t.account_id = a.id;

-- CROSS: every account × every offer (Cartesian product).
SELECT a.id, o.code FROM accounts a CROSS JOIN offers o;

-- SELF: each employee with their manager's name.
SELECT e.name AS employee, m.name AS manager
FROM employees e LEFT JOIN employees m ON e.manager_id = m.emp_id;
```

