package com.bank.joins;

import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class JoinsDao {
    private static final Logger log = Logger.getLogger(JoinsDao.class.getName());
    private final Connection conn;

    public JoinsDao(Connection conn) { this.conn = conn; }

    private List<String> run(String label, String sql) throws Exception {
        List<String> out = new ArrayList<>();
            try (Statement st = conn.createStatement();
            ResultSet rs = st.executeQuery(sql)) {
            int cols = rs.getMetaData().getColumnCount();
            while (rs.next()) {
                StringBuilder sb = new StringBuilder();
                for (int i = 1; i <= cols; i++) sb.append(rs.getString(i)).append(i < cols ? "|" : "");
                out.add(sb.toString());
            }
        }
        log.info(() -> label + " -> " + out);
        return out;
    }

    public void allJoins() throws Exception {
        run("INNER (accounts WITH txns)",
            "SELECT a.id, t.txn_id FROM accounts a JOIN transactions t ON t.account_id = a.id");
        run("LEFT (all accounts, dormant=NULL)",
            "SELECT a.id, t.txn_id FROM accounts a LEFT JOIN transactions t ON t.account_id = a.id");
        run("LEFT ANTI (never transacted)",
            "SELECT a.id FROM accounts a LEFT JOIN transactions t ON t.account_id = a.id WHERE t.txn_id IS NULL");
        run("FULL OUTER (both sides)",
            "SELECT a.id, t.txn_id FROM accounts a FULL OUTER JOIN transactions t ON t.account_id = a.id");
        run("CROSS (account × offer)",
            "SELECT a.id, o.code FROM accounts a CROSS JOIN offers o");
        run("SELF (employee + manager)",
            "SELECT e.name, m.name FROM employees e LEFT JOIN employees m ON e.manager_id = m.emp_id");
    }
}
