package com.bank.joins;

import java.sql.Connection;
import java.sql.DriverManager;
import java.util.logging.Logger;

public class JoinsDemo {
    private static final Logger log = Logger.getLogger(JoinsDemo.class.getName());

    public static void main(String[] args) throws Exception {
        try (Connection conn = DriverManager.getConnection(
                "jdbc:postgresql://localhost:5432/bankdb", "bank_app", "secret")) {
            new JoinsDao(conn).allJoins();
            log.info("INNER=matches; LEFT/RIGHT=keep one side; FULL=both; CROSS=product; SELF=same table.");
        }
    }
}
